    [["slider","cmp_slider","i-compare"],["side","cmp_side","i-frame"],["three","cmp_three","i-stack"],["result","cmp_result","i-gallery"]].forEach(function(m){
      var c=btn("chip"+(S.cmp===m[0]?" on":""), t(m[1]), m[2]); c.setAttribute("data-cmp", m[0]); c.setAttribute("aria-pressed", S.cmp===m[0]?"true":"false");
      c.onclick=function(){ setCmp(m[0]); }; modes.appendChild(c);
    });
