      var list=el("div","ps-versions"); list.id="psVersions";
      S.versions.forEach(function(x, i){
        var row=btn("ps-ver"+(i===S.cur?" on":""), ""); clear(row); row.setAttribute("aria-pressed", i===S.cur?"true":"false");
        var im=el("div","ps-ver-im"); im.style.backgroundImage="url("+x.dataUrl+")"; row.appendChild(im);
        var tx=el("div","ps-ver-t"); tx.appendChild(el("b",null,t("version_n",{n:S.versions.length-i}))); tx.appendChild(el("span","mut", modelLabel(x.model)+(x.size?" · "+x.size.toUpperCase():"")+" · "+hhmm(x.ts))); row.appendChild(tx);
        row.onclick=function(){ S.cur=i; render(); };
        list.appendChild(row);
      });
      w.appendChild(list);
